source=Path('work/probe-branch-restore-preparation-r1.py').read_text();exec(compile(source.split('rows=[]')[0],'<synthetic setup>','exec'))
rows=[]
for fmt in ['sha1','sha256']:
 r=repo('ignored-collision-'+fmt,fmt);run(r,'switch','-q','target');(r/'ignored.txt').write_bytes(b'new tracked ignored path\n');run(r,'add','-f','--','ignored.txt');run(r,'commit','-q','-m','tracked path');run(r,'switch','-q','main');(r/'ignored.txt').write_bytes(b'owned ignored sentinel\n');before=inv(r);p=run(r,'switch','-q','--no-overwrite-ignore','target',ok=False);assert p.returncode!=0 and before==inv(r);rows.append({'case':'ignored-target-collision-'+fmt,'pass':True,'exit':p.returncode,'all_bytes_modes_unchanged':True})
 r=repo('restore-stat-'+fmt,fmt);(r/'ordinary.txt').write_bytes(b'staged\n');run(r,'add','ordinary.txt');stage=run(r,'ls-files','--stage','-z').stdout;idx=(r/'.git/index').read_bytes();(r/'ordinary.txt').write_bytes(b'local unsaved longer\n');run(r,'restore','--worktree','--','ordinary.txt');assert (r/'ordinary.txt').read_bytes()==b'staged\n' and run(r,'ls-files','--stage','-z').stdout==stage;rows.append({'case':'restore-native-index-stat-only-'+fmt,'pass':True,'native_index_bytes_changed':(r/'.git/index').read_bytes()!=idx,'staged_semantics_unchanged':True,'design_implication':'Private native computation can refresh private stat-cache; worktree-only original publisher must not adopt the changed private index.'})
 r=repo('restore-delete-'+fmt,fmt);(r/'new-staged.txt').write_bytes(b'new staged path\n');run(r,'add','--','new-staged.txt');stage=run(r,'ls-files','--stage','-z').stdout;run(r,'restore','--source=HEAD','--worktree','--','new-staged.txt');assert not (r/'new-staged.txt').exists() and run(r,'ls-files','--stage','-z').stdout==stage;rows.append({'case':'restore-head-absence-deletes-tracked-worktree-only-'+fmt,'pass':True,'staged_semantics_unchanged':True,'worktree_target_absent':True})
 r=repo('builtin-normalization-'+fmt,fmt);(r/'.gitattributes').write_bytes(b'normalized.txt text eol=crlf ident\n');(r/'normalized.txt').write_bytes(b'$Id$\n');(r/'normalized.txt').chmod(0o755);run(r,'add','--','.gitattributes','normalized.txt');run(r,'commit','-q','-m','builtin attributes');oid=run(r,'rev-parse','HEAD:normalized.txt').stdout.strip();(r/'normalized.txt').write_bytes(b'changed\n');run(r,'restore','--source=HEAD','--worktree','--','normalized.txt');expected=b'$Id: '+oid+b' $\r\n';assert (r/'normalized.txt').read_bytes()==expected and stat.S_IMODE((r/'normalized.txt').stat().st_mode)==0o755;rows.append({'case':'builtin-eol-ident-executable-normalization-'+fmt,'pass':True,'expected_crlf_ident_expansion':True,'owner_execute_bit_preserved':True,'design_implication':'Checkout bytes must come from verified private native behavior, not raw blob bytes.'})
report={'status':'preparatory_behavior_only','count':len(rows),'cases':rows,'fixed_git':{'path':git,'sha256':hashlib.sha256(Path(git).read_bytes()).hexdigest()},'retained_synthetic_root':str(base),'limits':['New known-byte synthetic native behavior cases only, no previous passing matrix repeated.','No production publisher/kernel/admission/UI, no private project/credential/provider/Electron/Bun.','Content/mode inventory does not establish unchanged inode/times.','No accepted design/API or implementation/final approval.']};(base/'report-r2.json').write_text(json.dumps(report,indent=2)+'\n');Path('work/branch-restore-preparation-r2.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'count':len(rows),'report':str(base/'report-r2.json'),'status':report['status']}))
